const base = "https://signal-api.virya.music";

return [{
  json: {
    ready_url: `${base}/v1/health/ready`,
    metrics_url: `${base}/metrics`,
  },
}];

function responseOf(value) {
  const source = value && typeof value === 'object' ? value : {};
  const statusCode = Number(source.statusCode ?? source.status ?? 0);
  const body = source.body ?? source.data ?? source;

  return { statusCode, body };
}

function metric(text, name) {
  const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const match = String(text || '').match(
    new RegExp(`(?:^|\\n)${escaped}\\s+(-?\\d+(?:\\.\\d+)?)\\s*(?:\\n|$)`),
  );

  return match ? Number(match[1]) : null;
}

const readyResponse = responseOf(
  $('CrowdRelay — readiness').first().json,
);

const metricsResponse = responseOf(
  $('CrowdRelay — metrics').first().json,
);
const viryaResponse = responseOf(
  $('Virya — public surface').first().json,
);
const synesthesiaResponse = responseOf(
  $('Synesthesia — public surface').first().json,
);

let readyBody = readyResponse.body;

if (typeof readyBody === 'string') {
  try {
    readyBody = JSON.parse(readyBody);
  } catch {
    // The response may be plain text.
  }
}

const ready =
  readyResponse.statusCode >= 200 &&
  readyResponse.statusCode < 300 &&
  String(readyBody?.status ?? readyBody ?? '').toLowerCase() === 'ready';

const metricsText =
  typeof metricsResponse.body === 'string'
    ? metricsResponse.body
    : typeof metricsResponse.body?.data === 'string'
      ? metricsResponse.body.data
      : '';

const metricsReachable =
  metricsResponse.statusCode >= 200 &&
  metricsResponse.statusCode < 300 &&
  metricsText.length > 20;

const surfaceHealthy = response => {
  const body = typeof response.body === 'string'
    ? response.body
    : JSON.stringify(response.body ?? '');
  return response.statusCode >= 200 && response.statusCode < 400 && body.length > 120;
};
const viryaHealthy = surfaceHealthy(viryaResponse);
const synesthesiaHealthy = surfaceHealthy(synesthesiaResponse);

const values = {
  outbox_dead: metric(
    metricsText,
    'crowdrelay_outbox_dead',
  ),
  delivery_dead: metric(
    metricsText,
    'crowdrelay_webhook_delivery_dead',
  ),
  outbox_oldest: metric(
    metricsText,
    'crowdrelay_outbox_oldest_pending_seconds',
  ),
  delivery_oldest: metric(
    metricsText,
    'crowdrelay_webhook_delivery_oldest_pending_seconds',
  ),
};

const missingMetrics = Object.entries(values)
  .filter(([, value]) => value === null)
  .map(([name]) => name);

const currentOutboxDead = Math.max(
  0,
  Number(values.outbox_dead ?? 0),
);

const currentDeliveryDead = Math.max(
  0,
  Number(values.delivery_dead ?? 0),
);

const state = $getWorkflowStaticData('global');
const now = Date.now();

const initialized = state.watchdog_v2_initialized === true;

let acknowledgedOutboxDead = Number(
  state.watchdog_v2_ack_outbox_dead,
);

let acknowledgedDeliveryDead = Number(
  state.watchdog_v2_ack_delivery_dead,
);

if (!initialized || !Number.isFinite(acknowledgedOutboxDead)) {
  acknowledgedOutboxDead = currentOutboxDead;
}

if (!initialized || !Number.isFinite(acknowledgedDeliveryDead)) {
  acknowledgedDeliveryDead = currentDeliveryDead;
}

acknowledgedOutboxDead = Math.min(
  acknowledgedOutboxDead,
  currentOutboxDead,
);

acknowledgedDeliveryDead = Math.min(
  acknowledgedDeliveryDead,
  currentDeliveryDead,
);

const newOutboxDead = initialized
  ? Math.max(0, currentOutboxDead - acknowledgedOutboxDead)
  : 0;

const newDeliveryDead = initialized
  ? Math.max(0, currentDeliveryDead - acknowledgedDeliveryDead)
  : 0;

const activeReasons = [];

if (!ready) {
  activeReasons.push(
    `readiness=${readyResponse.statusCode || 'unreachable'}`,
  );
}

if (!metricsReachable) {
  activeReasons.push(
    `metrics=${metricsResponse.statusCode || 'unreachable'}`,
  );
}

if (!viryaHealthy) {
  activeReasons.push(
    `virya.music=${viryaResponse.statusCode || 'unreachable'}`,
  );
}

if (!synesthesiaHealthy) {
  activeReasons.push(
    `synesthesia=${synesthesiaResponse.statusCode || 'unreachable'}`,
  );
}

if ((values.outbox_oldest ?? 0) > 900) {
  activeReasons.push(
    `oldest outbox=${Math.round(values.outbox_oldest)}s`,
  );
}

if ((values.delivery_oldest ?? 0) > 900) {
  activeReasons.push(
    `oldest delivery=${Math.round(values.delivery_oldest)}s`,
  );
}

const newDeadReasons = [];

if (newOutboxDead > 0) {
  newDeadReasons.push(
    `new dead outbox=${newOutboxDead}`,
  );
}

if (newDeliveryDead > 0) {
  newDeadReasons.push(
    `new dead deliveries=${newDeliveryDead}`,
  );
}

const activeUnhealthy = activeReasons.length > 0;
const newDeadDetected = newDeadReasons.length > 0;

const activeSnapshot = {
  unhealthy: activeUnhealthy,
  reasons: activeReasons,
  ready_status: readyResponse.statusCode || 0,
  metrics_status: metricsResponse.statusCode || 0,
  virya_status: viryaResponse.statusCode || 0,
  synesthesia_status: synesthesiaResponse.statusCode || 0,
  outbox_oldest: values.outbox_oldest,
  delivery_oldest: values.delivery_oldest,
};

const activeFingerprint = JSON.stringify(activeSnapshot);
const previousActiveFingerprint = String(
  state.watchdog_v2_active_fingerprint || '',
);

const wasActiveUnhealthy =
  state.watchdog_v2_active_unhealthy === true;

const lastActiveSentAt = Number(
  state.watchdog_v2_last_active_sent_at || 0,
);

const activeChanged =
  activeFingerprint !== previousActiveFingerprint;

const reminderDue =
  activeUnhealthy &&
  now - lastActiveSentAt >= 6 * 60 * 60 * 1000;

const recovered =
  !activeUnhealthy &&
  wasActiveUnhealthy;

const activeNotification =
  activeUnhealthy &&
  (activeChanged || reminderDue);

const shouldNotify =
  newDeadDetected ||
  activeNotification ||
  recovered;

state.watchdog_v2_initialized = true;
state.watchdog_v2_ack_outbox_dead = currentOutboxDead;
state.watchdog_v2_ack_delivery_dead = currentDeliveryDead;
state.watchdog_v2_active_fingerprint = activeFingerprint;
state.watchdog_v2_active_unhealthy = activeUnhealthy;
state.watchdog_v2_last_checked_at = new Date(now).toISOString();

if (activeNotification || recovered) {
  state.watchdog_v2_last_active_sent_at = now;
}

if (!shouldNotify) {
  return [];
}

const lines = [];

if (recovered && !newDeadDetected) {
  lines.push('✅ **ViryaOS recovered**');
  lines.push('CrowdRelay i publiczne powierzchnie wróciły do zdrowego stanu.');
} else {
  lines.push('🚨 **ViryaOS health watchdog**');

  const reasons = [
    ...activeReasons,
    ...newDeadReasons,
  ];

  lines.push(`**Problem:** ${reasons.join(', ')}`);
}

lines.push(
  `**Outbox:** pending-oldest ${
    values.outbox_oldest ?? 'n/a'
  }s · dead ${currentOutboxDead}`,
);

lines.push(
  `**Webhook deliveries:** pending-oldest ${
    values.delivery_oldest ?? 'n/a'
  }s · dead ${currentDeliveryDead}`,
);

lines.push(
  `**Surfaces:** virya.music ${viryaResponse.statusCode || 'down'} · synesthesia ${synesthesiaResponse.statusCode || 'down'}`,
);

if (missingMetrics.length) {
  lines.push(
    `**Info:** brak metryk ${missingMetrics.join(', ')}.`,
  );
}

lines.push(
  `**Checked:** ${new Date(now).toISOString()}`,
);

return [{
  json: {
    content: lines.join('\n').slice(0, 1900),
    unhealthy: activeUnhealthy || newDeadDetected,
    fingerprint: JSON.stringify({
      active: activeSnapshot,
      new_outbox_dead: newOutboxDead,
      new_delivery_dead: newDeliveryDead,
    }),
    snapshot: {
      active: activeSnapshot,
      historical_dead: {
        outbox: currentOutboxDead,
        deliveries: currentDeliveryDead,
      },
      newly_detected_dead: {
        outbox: newOutboxDead,
        deliveries: newDeliveryDead,
      },
    },
  },
}];
